        if (!cmuCostCollectionWanted() || (cacExternalCollectorActive() && !settings.dashboard))
            return;
        const chatId = cacNormalizeId(meta?.chat_id || meta?.chatId || meta?.episode_id || getChatId());
        const messageId = cacFirstMessageId(meta);
        if (!chatId || !messageId)
            return;
