        let badge = group.querySelector('.cac-answer-cost');
        if (!(badge instanceof HTMLElement))
            badge = cacCreateBadge();
        if (badge.parentElement !== slot)
            slot.appendChild(badge);
        badge.dataset.messageId = messageId;
