        badge.title = `${estimated ? '사용 내역 시각을 기준으로 추정한' : '메시지 ID로 확인한'} 크래커 소모량: ${formatNumber(amount)}개`;
        badge.dataset.confidence = estimated ? 'estimated' : 'confirmed';
